'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
function model(){const c={window:{}};vm.runInNewContext(fs.readFileSync(path.join(__dirname,'swipe-boxes.js'),'utf8'),c);return c.window.PhoenixSwipeBoxModel;}
test('objective fitting follows the visible card rather than the tallest hidden card',()=>{const m=model(),cards=[{offsetLeft:10,offsetHeight:120},{offsetLeft:210,offsetHeight:380},{offsetLeft:410,offsetHeight:150}];assert.equal(m.nearestCard(cards,0),cards[0]);assert.equal(m.nearestCard(cards,205),cards[1]);assert.equal(m.nearestCard(cards,400),cards[2]);assert.equal(m.outerHeight(m.nearestCard(cards,0).offsetHeight,5,12,17),154);assert.equal(m.outerHeight(m.nearestCard(cards,205).offsetHeight,5,12,17),414);});
test('fit accounts for changing card widths, leading offsets and restored horizontal positions',()=>{const m=model(),cards=[{offsetLeft:35},{offsetLeft:202},{offsetLeft:369}];assert.equal(m.nearestCard(cards,167),cards[1]);assert.equal(m.nearestCard(cards,331),cards[2]);assert.equal(m.nearestCard([],0),null);});
test('the box includes card content, padding, border and native scrollbar without rounding clipping',()=>{const m=model();assert.equal(m.outerHeight(150,5,12,17),184);assert.equal(m.outerHeight(150,5.2,12.3,2),170);assert.equal(m.outerHeight(0,0,0,0),0);});

test('Velen enclosed selector accepts diagonal horizontal swipes but rejects taps and vertical-only movement',()=>{const m=model();assert.equal(m.swipeDirection(-70,100,true),1);assert.equal(m.swipeDirection(70,100,true),-1);assert.equal(m.swipeDirection(0,120,true),0);assert.equal(m.swipeDirection(8,8,true),0);assert.equal(m.swipeDirection(70,100,false),0);assert.equal(m.swipeDirection(-70,10,false),1);});
